// TTL 缓存 + stale-while-revalidate：整数逻辑时钟驱动，输出可断言
function createCache(ttlMs, swrMs) {
  const store = new Map();
  let now = 0;
  return {
    advance(ms) { now += ms; },
    read(key) {
      const e = store.get(key);
      if (!e) return { value: null, state: 'miss' };
      const age = now - e.at;
      if (age <= ttlMs) return { value: e.value, state: 'fresh' };
      if (age <= ttlMs + swrMs) return { value: e.value, state: 'stale' };  // 先给旧值，后台刷新
      return { value: null, state: 'expired' };
    },
    write(key, value) { store.set(key, { value, at: now }); return value; },
  };
}

const c = createCache(100, 200);      // ttl=100ms, swr 窗口=200ms
console.log('t0_read_miss=' + c.read('k').state);
c.write('k', 'v1');
